import { IonButton, IonHeader, IonIcon, IonModal, IonToolbar, useIonToast } from '@ionic/react';
import { trashBin } from 'ionicons/icons';
import React, { useRef, useState } from 'react';
import { ClientMasterFile } from '../../../../../types/types';
import kfiAxios from '../../../../utils/axios';
import ModalHeader from '../../../../ui/page/ModalHeader';
import { useOnlineStore } from '../../../../../store/onlineStore';
import { db } from '../../../../../database/db';
import { Trash } from 'lucide-react';

type DeleteCenterProps = {
  client: ClientMasterFile;
  getClients: (page: number, keyword?: string, sort?: string) => void;
  getClientsOffline: (page: number, keyword?: string, sort?: string) => void;
  searchkey: string;
  sortKey: string;
  currentPage: number;
  rowLength: number;
};

const DeleteClientMasterFile = ({ client, getClients, searchkey, sortKey, currentPage, rowLength, getClientsOffline }: DeleteCenterProps) => {
  const [present] = useIonToast();
  const [loading, setLoading] = useState(false);

  const modal = useRef<HTMLIonModalElement>(null);

  //online checker
  const online = useOnlineStore((state) => state.online);

  function dismiss() {
    modal.current?.dismiss();
  }

  async function handleDelete() {
    setLoading(true);
    if(online){
       try {
        const result = await kfiAxios.delete(`/customer/${client._id}`);
        const { success } = result.data;
        if (success) {
          const page = rowLength - 1 === 0 && currentPage > 1 ? currentPage - 1 : currentPage;
          getClients(page, searchkey, sortKey);
          dismiss();
          return;
        }
      } catch (error: any) {
        present({
          message: 'Failed to delete the client record. Please try again',
          duration: 1000,
        });
      } finally {
        setLoading(false);
      }
    }else {
       try {
        const row = await db.clientMasterFile
          .where("id")
          .equals(client.id)
          .first();


        if (!row) {
          present({
            message: "Client not found.",
            duration: 1200,
          });
          return;
        }

        if (row.isOldData === false) {
          await db.clientMasterFile.delete(row.id);
        } else {
          await db.clientMasterFile.update(row.id, {  _synced: false, action: 'delete' });
        }
        getClientsOffline(1)

      } catch (error) {
        getClientsOffline(1)

        present({
          message: "Failed to delete client record.",
          duration: 1200,
        });
      } finally {
        setLoading(false);
      }
  
    }
   
  }


  return (
    <>
      {/* <div className="text-end">
        <div
          id={`delete-cmf-modal-${client._id}`}
          className="w-full flex items-center justify-start gap-2 text-sm font-semibold cursor-pointer active:bg-slate-200 hover:bg-slate-50 text-slate-600 px-2 py-1"
        >
          <IonIcon icon={trashBin} className="text-[1rem]" /> Delete
        </div>
      </div> */}
      <IonButton
        type="button"
        fill="clear"
        id={`delete-cmf-modal-${client._id}`}
         className=" capitalize text-sm !text-zinc-700 w-fit"
      >
        <Trash size={20} className=' mr-1'/>
        <span>Delete</span>
      </IonButton>
      <IonModal
        ref={modal}
        trigger={`delete-cmf-modal-${client._id}`}
        backdropDismiss={false}
        className=" [--border-radius:0.35rem] auto-height [--max-width:30rem] [--width:95%]"
      >
        {/* <IonHeader>
          <IonToolbar className=" text-white [--min-height:1rem] h-12">
            <ModalHeader disabled={loading} title="Client - Delete Record" sub="Manage Account" dismiss={dismiss} />
          </IonToolbar>
        </IonHeader> */}
        <div className="inner-content !p-6">
            <ModalHeader disabled={loading} title="Client - Delete Record" sub="Are you sure you want to delete this record?" dismiss={dismiss} />

          {/* <p className="text-sm !font-medium text-center py-8 text-red-500">Are you sure you want to delete this record?</p> */}
          <div className="text-end mt-6 space-x-2">
            <IonButton onClick={handleDelete} disabled={loading} type="submit" fill="clear" className="!text-sm capitalize !bg-[#FA6C2F] text-white rounded-[4px]" strong={true}>
              {loading ? 'Deleting...' : 'Yes'}
            </IonButton>
            <IonButton disabled={loading} onClick={dismiss} color="tertiary" type="button" className="!text-sm capitalize" strong={true}>
              No
            </IonButton>
          </div>
        </div>
      </IonModal>
    </>
  );
};

export default DeleteClientMasterFile;
