import React, { useRef, useState } from 'react';
import { IonButton, IonModal, IonHeader, IonToolbar, useIonToast } from '@ionic/react';
import { useForm } from 'react-hook-form';
import { zodResolver } from '@hookform/resolvers/zod';
import ModalHeader from '../../../../ui/page/ModalHeader';
import LoanForm from '../components/LoanForm';
import { ProductLoanFormData, productSchema } from '../../../../../validations/loan.schema';
import kfiAxios from '../../../../utils/axios';
import formErrorHandler from '../../../../utils/form-error-handler';
import { TErrorData, TFormError } from '../../../../../types/types';
import checkError from '../../../../utils/check-error';
import { useOnlineStore } from '../../../../../store/onlineStore';
import { db } from '../../../../../database/db';

type CreateLoanProps = {
  getLoans: (page: number) => void;
  currentPage: number
};

const CreateLoan = ({ getLoans, currentPage }: CreateLoanProps) => {
  const [loading, setLoading] = useState(false);
  const [present] = useIonToast();
  const online = useOnlineStore((state) => state.online);
  
  

  const modal = useRef<HTMLIonModalElement>(null);

  const form = useForm<ProductLoanFormData>({
    resolver: zodResolver(productSchema),
    defaultValues: {
      code: '',
      loanCodes: [
        {
          module: '',
          loanType: '',
          acctCode: '',
          sortOrder: '',
        },
      ],
    },
  });

  function dismiss() {
    form.reset();
    modal.current?.dismiss();
  }

  async function onSubmit(data: ProductLoanFormData) {
    if(online){
      setLoading(true);
      try {
        const result = await kfiAxios.post('/loan', data);
        const { success } = result.data;
        if (success) {
          getLoans(1);
          dismiss();
          present({
            message: 'Product successfully created!.',
            duration: 1000,
          });
          return;
        }
      } catch (error: any) {
        const errs: TErrorData | string = error?.response?.data?.error || error.message;
        const errors: TFormError[] | string = checkError(errs);
        const fields: string[] = Object.keys(form.formState.defaultValues as Object);
        formErrorHandler(errors, form.setError, fields);
      } finally {
        setLoading(false);
      }
    } else {
       try {
        await db.productLoans.add({
          ...data,
          loanCodes: data.loanCodes.map((item) => ({
            ...item,
            acctCode: {
              _id: item.acctCode,
              description: item.acctCodeLabel
            }
          })) ,
          isOldData: false,
          _synced: false,  
          action: "create",
        });
        getLoans(currentPage);
        dismiss();
        present({
          message: "Loan Products successfully created!",
          duration: 1000,
        });
      } catch (error) {
        present({
          message: "Failed to save record. Please try again.",
          duration: 1200,
        });
      }
    }
  }

  return (
    <>
      <div className="text-end">
        <IonButton fill="clear" id="create-loan-modal" className="max-h-8 min-h-[2rem] bg-[#FA6C2F] text-white capitalize font-semibold rounded-md" strong>
          + Add Record
        </IonButton>
      </div>
      <IonModal
        ref={modal}
        trigger="create-loan-modal"
        backdropDismiss={false}
        className=" [--border-radius:0.35rem] auto-height [--max-width:84rem] [--width:95%]"
      >
        {/* <IonHeader>
          <IonToolbar className=" text-white [--min-height:1rem] h-12">
            <ModalHeader disabled={loading} title="Product - Add Record" sub="System" dismiss={dismiss} />
          </IonToolbar>
        </IonHeader> */}
        <div className="inner-content !p-6">
            <ModalHeader disabled={loading} title="Product - Add Record" sub="Manage product records." dismiss={dismiss} />

          <div>
            <form onSubmit={form.handleSubmit(onSubmit)} className=' mt-4'>
              <LoanForm form={form} loading={loading} />
              <div className="text-end mt-6 space-x-2">
                <IonButton disabled={loading} type="submit" fill="clear" className="!text-sm capitalize !bg-[#FA6C2F] text-white rounded-[4px]" strong={true}>
                  {loading ? 'Saving...' : 'Save'}
                </IonButton>
                <IonButton disabled={loading} onClick={dismiss} color="danger" type="button" className="!text-sm capitalize" strong={true}>
                  Cancel
                </IonButton>
              </div>
            </form>
          </div>
        </div>
      </IonModal>
    </>
  );
};

export default CreateLoan;
