import React, { useState } from 'react';
import { IonButton, IonModal, IonHeader, IonToolbar, useIonToast } from '@ionic/react';
import { useForm, UseFormReturn } from 'react-hook-form';
import { zodResolver } from '@hookform/resolvers/zod';
import ModalHeader from '../../../../ui/page/ModalHeader';
import { ExpenseVoucherFormData, expenseVoucherSchema, UpdateExpenseVoucherFormData } from '../../../../../validations/expense-voucher.schema';
import ExpenseVoucherFormTable from '../components/ExpenseVoucherFormTable';
import ExpenseVoucherForm from '../components/ExpenseVoucherForm';
import kfiAxios from '../../../../utils/axios';
import { TErrorData, TFormError } from '../../../../../types/types';
import checkError from '../../../../utils/check-error';
import formErrorHandler from '../../../../utils/form-error-handler';
import { formatDateInput } from '../../../../utils/date-utils';
import { formatNumber, removeAmountComma } from '../../../../ui/utils/formatNumber';
import Signatures from '../../../../ui/common/Signatures';
import { useOnlineStore } from '../../../../../store/onlineStore';
import { db } from '../../../../../database/db';
import { formatEVEntries, formatJVEntries } from '../../../../ui/utils/fomatData';

type CreateExpenseVoucherProps = {
  getExpenseVouchers: (page: number, keyword?: string, sort?: string) => void;
};

const CreateExpenseVoucher = ({ getExpenseVouchers }: CreateExpenseVoucherProps) => {
  const [present] = useIonToast();

  const [isOpen, setIsOpen] = useState(false);
  const [loading, setLoading] = useState(false);
  const online = useOnlineStore((state) => state.online);
  const user = localStorage.getItem('user')

  

  const form = useForm<ExpenseVoucherFormData>({
    resolver: zodResolver(expenseVoucherSchema),
    defaultValues: {
      code: '',
      supplier: '',
      supplierId: '',
      refNo: '',
      date: formatDateInput(new Date().toISOString()),
      acctMonth: `${new Date().getMonth() + 1}`,
      acctYear: `${new Date().getFullYear()}`,
      checkNo: '',
      checkDate: formatDateInput(new Date().toISOString()),
      bank: '',
      bankLabel: '',
      amount: '0',
      remarks: '',
      entries: [],
    },
  });

  function dismiss() {
    form.reset();
    setIsOpen(false);
  }

  const entries = form.watch('entries') || []

  const difference = `${formatNumber(Math.abs(entries.reduce((acc, current) => acc + Number(removeAmountComma(current.debit || '')), 0) - entries.reduce((acc, current) => acc + Number(removeAmountComma(current.credit || 0)), 0)))}`


  async function onSubmit(data: ExpenseVoucherFormData) {
    if (Number(removeAmountComma(difference)) !== 0) {
        form.setError('root', { message: `Debit and Credit must be balanced.` });
        return;
      }
   if(online){
     setLoading(true);
      try {
        data.amount = removeAmountComma(data.amount);
        data.entries = data.entries.map((entry, index) => ({ ...entry, debit: removeAmountComma(entry.debit), credit: removeAmountComma(entry.credit), line: index + 1}));
        const result = await kfiAxios.post('expense-voucher', data);
        const { success } = result.data;
        if (success) {
          getExpenseVouchers(1);
          present({
            message: 'Expense voucher successfully added.',
            duration: 1000,
          });
          dismiss();
          return;
        }
        present({
          message: 'Failed to add a new expense voucher. Please try again.',
          duration: 1000,
        });
      } catch (error: any) {
        const errs: TErrorData | string = error?.response?.data?.error || error?.response?.data?.msg || error.message;
        const errors: TFormError[] | string = checkError(errs);
        const fields: string[] = Object.keys(form.formState.defaultValues as Object);
        formErrorHandler(errors, form.setError, fields);
      } finally {
        setLoading(false);
      }
   } else {
    try {
      await db.expenseVouchers.add({
        ...data,
         entries: data.entries.map((item, index) => ({
            ...item,
            line: index + 1,
            acctCode: {
              _id: item.acctCodeId,
              code: item.acctCode,
              description: item.description
            },
            client:{
              center: item.particular,
              name: item.clientLabel,
              _id: item.client,
            },
           
            action: 'create',
            _synced: false,
          })), 
         bank:{
            code: data.bankLabel,
            description: data.bankLabel,
            _id: data.bank
          },
           supplier:{
              code: data.supplier,
              description: data.supplier,
              _id: data.supplierId,
            },
          encodedBy:{
            username: user
          },
        _synced: false,  
        action: "create",
        isOldData: false
      });
      getExpenseVouchers(1);
      dismiss();
      present({
        message: "Expense voucher successfully created!",
        duration: 1000,
      });
    } catch (error) {
      present({
        message: "Failed to save record. Please try again.",
        duration: 1200,
      });
    }
   }
  }

  const amount = form.watch("amount") || 0;

  return (
    <>
      <IonButton onClick={() => setIsOpen(true)} fill="clear" className=" h-10 bg-[#FA6C2F] text-white capitalize font-semibold rounded-xl" strong>
        + Add
      </IonButton>
      <IonModal
        isOpen={isOpen}
        backdropDismiss={false}
        className=" [--border-radius:0.7rem] auto-height [--max-width:74rem] [--width:95%]"
      >
        {/* <IonHeader>
          <IonToolbar className=" text-white [--min-height:1rem] h-12">
            <ModalHeader title="Expense Voucher - Add Record" sub="Transaction" dismiss={dismiss} />
          </IonToolbar>
        </IonHeader> */}
        <div className="inner-content !p-6 max-h-[85%] h-full flex flex-col">
            <ModalHeader title="Expense Voucher - Add Record" sub="Manage expense voucher records." dismiss={dismiss} />

          <form onSubmit={form.handleSubmit(onSubmit)} className="h-full flex flex-col mt-4">
            <div>
              <ExpenseVoucherForm form={form} loading={loading} />
            </div>
            <div className="flex-1 mt-2">
              <ExpenseVoucherFormTable form={form} loading={loading} />
            </div>
             <div className="px-3">
                <div className="grid grid-cols-3">
                  <div className="flex items-center justify-start gap-2 text-sm border-4 px-2 py-1 [&>div]:!font-semibold">
                    <div>Diff: </div>
                    <div>{`${formatNumber(Math.abs(form.watch('entries').reduce((acc, current) => acc + Number(removeAmountComma(current.debit as string)), 0) - form.watch('entries').reduce((acc, current) => acc + Number(removeAmountComma(current.credit as string)), 0)))}`}</div>
                  </div>

                  <div className="flex items-center justify-start gap-2 text-sm border-4 px-2 py-1 [&>div]:!font-semibold col-span-2">
                    <div>Total: </div>
                    <div>{`${amount.toLocaleString()}`}</div>
                  </div>
                 
                </div>
              </div>

                 {form.formState.errors.root && <div className="text-sm text-red-600 italic text-center">{form.formState.errors.root.message}</div>}
              <Signatures open={isOpen} type={'expense voucher'} preparedBy={user || ''} recieveByorDate={form.watch('date')}/>
            
           

            <div className="text-end mt-6 px-3">
              <IonButton disabled={loading} type="submit" fill="clear" className="!text-sm capitalize !bg-[#FA6C2F] text-white rounded-[4px]" strong={true}>
                {loading ? 'Saving...' : 'Save'}
              </IonButton>
              <IonButton disabled={loading} onClick={dismiss} color="danger" type="button" className="!text-sm capitalize" strong={true}>
                Cancel
              </IonButton>
            </div>
          </form>
        </div>
      </IonModal>
    </>
  );
};

export default CreateExpenseVoucher;
