import { IonButton, IonHeader, IonModal, IonToolbar, useIonToast } from '@ionic/react';
import React, { useState } from 'react';
import ModalHeader from '../../../../../ui/page/ModalHeader';
import { AcknowledgementEntry, Release, ReleaseEntry, TErrorData, TFormError } from '../../../../../../types/types';
import { useForm } from 'react-hook-form';
import { zodResolver } from '@hookform/resolvers/zod';
import { EntryFormData } from '../../../../../../validations/loan-release.schema';
import kfiAxios from '../../../../../utils/axios';
import checkError from '../../../../../utils/check-error';
import formErrorHandler from '../../../../../utils/form-error-handler';
import { AcknowledgementEntryFormData, acknowledgementEntrySchema } from '../../../../../../validations/acknowledgement.schema';
import AcknowledgementEntryForm from '../../components/ReleaseEntryForm';
import { ReleaseEntryFormData, releaseEntrySchema } from '../../../../../../validations/release.schema';
import { removeAmountComma } from '../../../../../ui/utils/formatNumber';
import { TData } from '../../components/UpdateReleaseEntries';

type AddEntryProps = {
  releaseId: string;
  getEntries: (page: number) => void;
  entries: ReleaseEntry[] 
    setEntries: React.Dispatch<React.SetStateAction<ReleaseEntry[]>>;
    setData: React.Dispatch<React.SetStateAction<TData>>;
    transaction: Release;
};

const AddEntry = ({ releaseId, getEntries, setData, setEntries }: AddEntryProps) => {
  const [present] = useIonToast();
  const [isOpen, setIsOpen] = useState(false);
  const [loading, setLoading] = useState(false);

  const form = useForm<ReleaseEntryFormData>({
    resolver: zodResolver(releaseEntrySchema),
    defaultValues: {
      loanReleaseEntryId: '',
      dueDate: '',
      noOfWeeks: '',
      name: '',
      particular: '',
      acctCodeId: '',
      acctCode: '',
      description: '',
      debit: '0',
      credit: '0',
    },
  });

  function dismiss() {
      form.reset();
      setIsOpen(false);
    }
    //   setLoading(true);
    //   try {
    //     data.debit = removeAmountComma(data.debit as string);
    //     data.credit = removeAmountComma(data.credit as string);
    //     const result = await kfiAxios.post(`/acknowledgement/entries/${acknowledgementId}`, data);
    //     const { success } = result.data;
    //     if (success) {
    //       getEntries(1);
    //       present({ message: 'Entry successfully added', duration: 1000 });
    //       dismiss();
    //       return;
    //     }
    //     present({ message: 'Failed to update the entry', duration: 1000 });
    //   } catch (error: any) {
    //     const errs: TErrorData | string = error?.response?.data?.error || error?.response?.data?.msg || error.message;
    //     const errors: TFormError[] | string = checkError(errs);
    //     const fields: string[] = Object.keys(form.formState.defaultValues as Object);
    //     formErrorHandler(errors, form.setError, fields);
    //   } finally {
    //     setLoading(false);
    //   }
    // };
  
    function generateObjectId(): string {
      const timestamp = Math.floor(Date.now() / 1000).toString(16);
      const random = 'xxxxxxxxxxxxxxxx'.replace(/x/g, () =>
        Math.floor(Math.random() * 16).toString(16)
      ); 
      return timestamp + random; 
    }
  
     function normalizeCVNumber(cv: string): string {
      if (!cv) return "";
  
      return cv.replace(/^(CV#)+/, "CV#");
    }
  
  
      const onSubmit = async (data: AcknowledgementEntryFormData) => {
           if (data.debit === '' && data.credit === '') {
             form.setError('root', { message: 'No data to save. Please add a debit/credit.' });
             return;
           }
       
           setLoading(true);
           try {
             data.debit = removeAmountComma(data.debit as string);
             data.credit = removeAmountComma(data.credit as string);
       
             console.log(data)
       
             const debit = Number(removeAmountComma(data.debit));
             const credit = Number(removeAmountComma(data.credit));
       
             setEntries((prev: ReleaseEntry[]) => {
              const nextLine = prev.length > 0 
                ? Math.max(...prev.map(e => e.line)) + 1 
                : 1;
             const newEntry: ReleaseEntry = {
               _id: generateObjectId(),
               //  acknowledgement: '',
               loanReleaseEntryId: {
                 _id: data.loanReleaseEntryId ?? '',
                 transaction: {
                   _id: "",
                   code: normalizeCVNumber(data.cvNo ?? '') ?? '',
                   dueDate: data.dueDate ?? '',

                   noOfWeeks: 20
                 },
                 client: {
                   _id: data.client ?? '',
                   name: data.name ?? ''
                 },
               },
               acctCode: {
                 _id: data.acctCodeId,
                 code: data.acctCode,
                 description: data.description ?? ''
               },
               debit: debit,
               credit: credit,
               particular: data.particular ?? '',
               createdAt: new Date().toISOString(),
               cvNo: data.cvNo ?? '',
               release: '',
               _synced: false,
              action: "create",
              line: nextLine,
             }
              
       
             return [...prev, newEntry];
           });
       
           
           setData((prev: any) => {
             const nextLine = prev.entries.length > 0 
                ? Math.max(...prev.entries.map((e: { line: any; }) => e.line)) + 1 
                : 1;
           const newEntry: ReleaseEntry = {
             _id: generateObjectId(),
             // acknowledgement: '',
             loanReleaseEntryId: {
               _id: data.loanReleaseEntryId ?? '',
               transaction: {
                 _id: "",
                 code: normalizeCVNumber(data.cvNo ?? '') ?? '',
                 dueDate: data.dueDate ?? '',
                 noOfWeeks: 20
               },
               client: {
                 _id: data.client ?? '',
                 name: data.name ?? ''
               },
             },
             acctCode: {
               _id: data.acctCodeId,
               code: data.acctCode,
               description: data.description ?? ''
             },
             debit: debit,
             credit: credit,
             particular: data.particular ?? '',
             createdAt: new Date().toISOString(),
             cvNo: data.cvNo ?? '',
             release: '',
             _synced: false,
              action: "create",
              line: nextLine,
           }
       
             return {
               ...prev,
               entries: [...prev.entries, newEntry],
             };
           });
      
             present({ message: 'Entry added successfully', duration: 1200 });
             dismiss();
           } catch (err) {
             present({ message: 'Failed to add entry locally', duration: 1200 });
           } finally {
             setLoading(false);
           }
         };

  return (
    <>
      <IonButton onClick={() => setIsOpen(true)} type="button" fill="clear" className="max-h-10 min-h-6 bg-[#FA6C2F] text-white capitalize font-semibold rounded-md" strong>
        + Add Entries
      </IonButton>
      <IonModal
        isOpen={isOpen}
        backdropDismiss={false}
        className=" [--border-radius:0.35rem] auto-height md:[--max-width:30rem] md:[--width:100%] lg:[--max-width:30rem] lg:[--width:50%] [--width:95%]"
      >
        {/* <IonHeader>
          <IonToolbar className=" text-white [--min-height:1rem] h-12">
            <ModalHeader title="Acknowledgement - Add Entry" sub="Transaction" dismiss={dismiss} />
          </IonToolbar>
        </IonHeader> */}
        <div className="inner-content !p-6">
            <ModalHeader title="Acknowledgement - Add Entry" sub="Manage acknowledgement record." dismiss={dismiss} />

          <form onSubmit={form.handleSubmit(onSubmit)} className='mt-4'>
            <AcknowledgementEntryForm form={form} loading={loading} />
            {form.formState.errors.root && <div className="text-sm text-center italic text-red-600">{form.formState.errors.root.message}</div>}
            <div className="text-end space-x-1 px-2">
              <IonButton disabled={loading} type="submit" fill="clear" className="!text-sm capitalize !bg-[#FA6C2F] text-white rounded-[4px]" strong={true}>
                {loading ? 'Saving...' : 'Save'}
              </IonButton>
              <IonButton disabled={loading} onClick={dismiss} color="danger" type="button" className="!text-sm capitalize" strong={true}>
                Cancel
              </IonButton>
            </div>
          </form>
        </div>
      </IonModal>
    </>
  );
};

export default AddEntry;
