import React, { useEffect, useRef, useState } from 'react';
import { IonButton, IonModal, IonHeader, IonToolbar, IonIcon, useIonToast } from '@ionic/react';
import { createSharp } from 'ionicons/icons';
import { useForm } from 'react-hook-form';
import { zodResolver } from '@hookform/resolvers/zod';
import ModalHeader from '../../../../ui/page/ModalHeader';
import GroupAccountForm from '../components/GroupAccountForm';
import { GroupAccountFormData, groupAccountSchema } from '../../../../../validations/group-account.schema';
import { TGroupAccount } from '../GroupAccount';
import { GroupAccount, TErrorData, TFormError } from '../../../../../types/types';
import kfiAxios from '../../../../utils/axios';
import formErrorHandler from '../../../../utils/form-error-handler';
import checkError from '../../../../utils/check-error';
import { useOnlineStore } from '../../../../../store/onlineStore';
import { db } from '../../../../../database/db';
import { randomUUID } from 'crypto';

type UpdateGroupAccountProps = {
  groupAccount: GroupAccount;
  setData: React.Dispatch<React.SetStateAction<TGroupAccount>>;
  getGroupAccounts: (page: number) => void;
  currentPage: number
};

const UpdateGroupAccount = ({ groupAccount, setData, getGroupAccounts, currentPage }: UpdateGroupAccountProps) => {
  const [loading, setLoading] = useState(false);
  const modal = useRef<HTMLIonModalElement>(null);
  const [present] = useIonToast();
  const online = useOnlineStore((state) => state.online);
  

  const form = useForm<GroupAccountFormData>({
    resolver: zodResolver(groupAccountSchema),
    defaultValues: {
      code: groupAccount.code,
    },
  });

  useEffect(() => {
    if (groupAccount) {
      form.reset({
        code: groupAccount.code,
      });
    }
  }, [groupAccount, form]);

  function dismiss() {
    form.reset();
    modal.current?.dismiss();
  }

  async function onSubmit(data: GroupAccountFormData) {
    if(online){
      setLoading(true);
      try {
        const result = await kfiAxios.put(`/group-account/${groupAccount._id}`, data);
        const { success } = result.data;
        if (success) {
          setData(prev => {
            let clone = [...prev.groupAccounts];
            let index = clone.findIndex(e => e._id === result.data.groupAccount._id);
            clone[index] = { ...result.data.groupAccount };
            return { ...prev, groupAccounts: clone };
          });
          dismiss();
          present({
            message: 'Group account successfully updated!.',
            duration: 1000,
          });
          getGroupAccounts(currentPage)
          return;
        }
      } catch (error: any) {
        const errs: TErrorData | string = error?.response?.data?.error || error.message;
        const errors: TFormError[] | string = checkError(errs);
        const fields: string[] = Object.keys(form.formState.defaultValues as Object);
        formErrorHandler(errors, form.setError, fields);
      } finally {
        setLoading(false);
      }
    } else {
       try {
               const existing = await db.groupOfAccounts.get(groupAccount.id);
       
               if (!existing) {
                 console.warn("Data not found");
                 return;
               }
       
               const updated = {
                 ...existing,
                 ...data, 
                 code: data.code,
                  action: existing.isOldData ? 'update' : 'create',
                  _synced: false,
               };
       
               await db.groupOfAccounts.update(groupAccount.id, updated);
       
               setData(prev => {
                 const clone = [...prev.groupAccounts];
                 const index = clone.findIndex(c => c.id === groupAccount.id);
       
                 if (index !== -1) {
                   clone[index] = updated;
                 }
       
                 return { ...prev, groupAccounts: clone };
               });
       
               dismiss();
               present({
                 message: "Data successfully updated!",
                 duration: 1000,
               });
       
             } catch (error) {
               console.error("Offline update failed:", error);
             }
        
    }
  }

  return (
    <>
      {/* <div className="text-end">
        <div
          id={`update-group-account-modal-${groupAccount._id}`}
          className="w-full flex items-center justify-start gap-2 text-sm font-semibold cursor-pointer active:bg-slate-200 hover:bg-slate-50 text-slate-600 px-2 py-1"
        >
          <IonIcon icon={createSharp} className="text-[1rem]" /> Edit
        </div>
      </div> */}
      <IonButton
        id={`update-group-account-modal-${groupAccount._id}`}
        type="button"
        fill="clear"
        className="space-x-1 rounded-md w-16 h-7 ![--padding-start:0] ![--padding-end:0] ![--padding-top:0] ![--padding-bottom:0]  bg-blue-50 text-blue-900 capitalize min-h-4 text-xs"
      >
        <IonIcon icon={createSharp} className="text-xs" />
        <span>Edit</span>
      </IonButton>
      <IonModal
        ref={modal}
        trigger={`update-group-account-modal-${groupAccount._id}`}
        backdropDismiss={false}
        className=" [--border-radius:0.35rem] auto-height md:[--max-width:30rem] md:[--width:100%] lg:[--max-width:30rem] lg:[--width:50%] [--width:95%]"
      >
        {/* <IonHeader>
          <IonToolbar className=" text-white [--min-height:1rem] h-12">
            <ModalHeader title="Group Account - Edit Record" sub="System" dismiss={dismiss} />
          </IonToolbar>
        </IonHeader> */}
        <div className="inner-content !p-6">
            <ModalHeader title="Group Account - Edit Record" sub="Manage group account records." dismiss={dismiss} />

          <div>
            <form onSubmit={form.handleSubmit(onSubmit)}>
              <GroupAccountForm form={form} loading={loading} />
              <div className="text-end mt-6 space-x-2">
                <IonButton disabled={loading} type="submit" fill="clear" className="!text-sm capitalize !bg-[#FA6C2F] text-white rounded-[4px]" strong={true}>
                  {loading ? 'Saving...' : 'Save'}
                </IonButton>
                <IonButton disabled={loading} onClick={dismiss} color="danger" type="button" className="!text-sm capitalize" strong={true}>
                  Cancel
                </IonButton>
              </div>
            </form>
          </div>
        </div>
      </IonModal>
    </>
  );
};

export default UpdateGroupAccount;
