import { IonButton, IonHeader, IonInput, IonModal, IonToolbar } from '@ionic/react';
import React, { useEffect, useRef, useState } from 'react';
import SelectionHeader from './SelectionHeader';
import { Table, TableBody, TableCell, TableHead, TableHeader, TableHeadRow, TableRow } from '../table/Table';
import FormIonItem from '../utils/FormIonItem';
import classNames from 'classnames';
import kfiAxios from '../../utils/axios';
import TableLoadingRow from '../forms/TableLoadingRow';
import TableNoRows from '../forms/TableNoRows';
import { FieldValues, Path, PathValue, UseFormClearErrors, UseFormSetValue } from 'react-hook-form';
import TablePagination from '../forms/TablePagination';
import { Search01Icon } from 'hugeicons-react';
import { useOnlineStore } from '../../../store/onlineStore';
import { TABLE_LIMIT } from '../../utils/constants';
import { db } from '../../../database/db';

type Option = {
  _id: string;
  name: string;
  acctNumber: string;
  center: { centerNo: string };
};

export type TClient = {
  clients: Option[];
  totalPages: number;
  nextPage: boolean;
  prevPage: boolean;
  loading: boolean;
};

type ClientSelectionProps<T extends FieldValues> = {
  setValue: UseFormSetValue<T>;
  clearErrors: UseFormClearErrors<T>;
  clientLabel: Path<T>;
  clientValue: Path<T>;
  clientParticular?: Path<T>;
  className?: string;
  center?: string;
};

const ClientSelection = <T extends FieldValues>({ clientLabel, clientValue, setValue, clearErrors, className = '', center = '', clientParticular }: ClientSelectionProps<T>) => {
  const [isOpen, setIsOpen] = useState(false);
  const [loading, setLoading] = useState(false);
  const ionInputRef = useRef<HTMLIonInputElement>(null);

  const [currentPage, setCurrentPage] = useState<number>(1);
  const online = useOnlineStore((state) => state.online);
  

  const [data, setData] = useState<TClient>({
    clients: [],
    loading: false,
    totalPages: 0,
    nextPage: false,
    prevPage: false,
  });

  function dismiss() {
    setIsOpen(false);
  }

  const handleOpen = () => {
    setIsOpen(true);
  };

  const handleSearch = async (page: number) => {
   if(online){
     const value = ionInputRef.current?.value || '';
      setLoading(true);
      try {
        const filter: any = { keyword: value, page, limit: 10 };
        if (center) filter.center = center;
        const result = await kfiAxios.get('customer/selection', { params: filter });
        const { success, clients, hasPrevPage, hasNextPage, totalPages } = result.data;
        if (success) {
          setData(prev => ({
            ...prev,
            clients: clients,
            totalPages: totalPages,
            nextPage: hasNextPage,
            prevPage: hasPrevPage,
          }));
          setCurrentPage(page);
          return;
        }
      } catch (error) {
      } finally {
        setLoading(false);
      }
   } else {
    try {
        const limit = TABLE_LIMIT;
        let allData = await db.clientMasterFile.toArray();
        let allOptions: Option[] = allData.map(item => ({
           _id: item._id,
            name: item.name,
            acctNumber: item.acctNumber,
            center: { centerNo: item.center.centerNo },
        }));

        console.log(allData)
        
       const totalItems = allOptions.length;
        const totalPages = Math.ceil(totalItems / limit);
        const start = (page - 1) * limit;
        const end = start + limit;
        const finalData = allOptions.slice(start, end);
        const hasPrevPage = page > 1;
        const hasNextPage = page < totalPages;
        setData(prev => ({
           ...prev,
          clients: finalData,
          totalPages: totalPages,
          nextPage: hasNextPage,
          prevPage: hasPrevPage,
        }));
        setCurrentPage(page);
      } catch (error) {
        console.error("Erro while fetching data.", error);
      } finally {
        setData(prev => ({ ...prev, loading: false }));
      }
   }
  };

  const handleSelectClient = (client: Option) => {
    const clientName = client.name as PathValue<T, Path<T>>;
    const clientId = client._id as PathValue<T, Path<T>>;
    const particular = `${client.center.centerNo} - ${client.name}`;

    console.log(clientParticular)
    

    setValue(clientLabel as Path<T>, clientName as any);
    setValue(clientValue as Path<T>, clientId as any);
    // setValue(clientParticular as Path<T>, particular as any);
    clientParticular && setValue(clientParticular as Path<T>, particular as any);
    clearErrors(clientLabel);
    clearErrors(clientValue);
    clientParticular && clearErrors(clientParticular);
    setData({
      clients: [],
      loading: false,
      totalPages: 0,
      nextPage: false,
      prevPage: false,
    });
    dismiss();
  };

  const handlePagination = (page: number) => handleSearch(page);

  useEffect(() => {
    isOpen && handleSearch(1);
  }, [isOpen]);

  return (
    <>
      <div className="text-end">
        <IonButton onClick={handleOpen} fill="clear" className={classNames('max-h-9 min-h-9 btn-color text-white capitalize font-semibold rounded-md m-0 text-xs', className)} strong>
          <Search01Icon size={15} stroke='.8' className=' mr-1'/>
          Find
        </IonButton>
      </div>
      <IonModal
        isOpen={isOpen}
        backdropDismiss={false}
        className=" [--border-radius:0.35rem] auto-height [--width:95%] md:[--max-width:70%] md:[--width:100%] lg:[--max-width:50%] lg:[--width:50%]"
      >
        {/* <IonHeader>
          <IonToolbar className=" text-white [--min-height:1rem] h-10">
            <SelectionHeader dismiss={dismiss} disabled={loading} title="Client Selection" />
          </IonToolbar>
        </IonHeader> */}
        <div className="inner-content !p-6  border-2 !border-slate-200">
            <SelectionHeader dismiss={dismiss} disabled={loading} title="Client Selection" />

          <div className="">
            <div className="flex items-center flex-wrap justify-start gap-2">
              <div className="flex items-center min-w-20">
                <FormIonItem className="flex-1">
                  <IonInput
                    ref={ionInputRef}
                    clearInput
                    type="search"
                    aria-label="Type here"
                    placeholder="Type here"
                    disabled={data.loading}
                    className={classNames(
                      'text-sm !bg-white rounded-md !px-2 ![--highlight-color-focused:none] md:![--padding-bottom:0] ![--padding-top:0] ![--padding-start:0] border border-slate-400 ![--min-height:1rem] !min-h-[1rem]',
                    )}
                  />
                </FormIonItem>
                <IonButton
                  disabled={data.loading}
                  onClick={() => handleSearch(1)}
                  type="button"
                  fill="clear"
                  className="max-h-10 min-h-[2rem] bg-[#FA6C2F] text-white capitalize font-semibold rounded-md text-xs"
                  strong
                >
                  <Search01Icon size={15} stroke='.8' className=' mr-1'/>

                  {data.loading ? 'Finding...' : 'Find'}
                </IonButton>
              </div>
            </div>
          </div>
          <div className="relative overflow-auto">
            <Table>
              <TableHeader>
                <TableHeadRow className="border-b-0 bg-slate-100">
                  <TableHead className="!py-2">Account Number</TableHead>
                  <TableHead className="!py-2">Name</TableHead>
                </TableHeadRow>
              </TableHeader>
              <TableBody>
                {data.loading && <TableLoadingRow colspan={2} />}
                {!data.loading && data.clients.length < 1 && <TableNoRows colspan={5} label="No client found" />}
                {!data.loading &&
                  data.clients.map((data: Option) => (
                    <TableRow onClick={() => handleSelectClient(data)} key={data._id} className="border-b-0 [&>td]:!py-1 cursor-pointer">
                      <TableCell className="">{data.acctNumber}</TableCell>
                      <TableCell className="">{data.name}</TableCell>
                    </TableRow>
                  ))}
              </TableBody>
            </Table>
          </div>
          <TablePagination currentPage={currentPage} totalPages={data.totalPages} onPageChange={handlePagination} disabled={data.loading} />
        </div>
      </IonModal>
    </>
  );
};

export default ClientSelection;
