import { IonButton, IonHeader, IonModal, IonToolbar, useIonToast } from '@ionic/react';
import React, { useRef, useState } from 'react';
import kfiAxios from '../../../../utils/axios';
import ModalHeader from '../../../../ui/page/ModalHeader';
import { PrinterIcon } from 'hugeicons-react';

const PrintAllWeeklySavingsTable = () => {
  const [present] = useIonToast();
  const [loading, setLoading] = useState(false);

  const modal = useRef<HTMLIonModalElement>(null);

  function dismiss() {
    modal.current?.dismiss();
  }

  async function handlePrint() {
    setLoading(true);
    try {
      const result = await kfiAxios.get(`/weekly-saving/print-all`, { responseType: 'blob' });
      const pdfBlob = new Blob([result.data], { type: 'application/pdf' });
      const pdfUrl = URL.createObjectURL(pdfBlob);
      window.open(pdfUrl, '_blank');
      setTimeout(() => URL.revokeObjectURL(pdfUrl), 1000);
    } catch (error: any) {
      present({
        message: 'Failed to print the weekly savings records. Please try again',
        duration: 1000,
      });
    } finally {
      setLoading(false);
    }
  }

  return (
    <>
      <IonButton fill="clear" id="print_all_wst" className="max-h-10 min-h-6 bg-[#FA6C2F] text-white capitalize font-semibold rounded-md" strong>
        <PrinterIcon size={15} stroke='.8' className=' mr-1'/>
        Print
      </IonButton>
      <IonModal
        ref={modal}
        trigger={`print_all_wst`}
        backdropDismiss={false}
        className=" [--border-radius:0.35rem] auto-height [--max-width:32rem] [--width:95%]"
      >
        {/* <IonHeader>
          <IonToolbar className=" text-white [--min-height:1rem] h-12">
            <ModalHeader disabled={loading} title="Weekly Savings - Print All" sub="System" dismiss={dismiss} />
          </IonToolbar>
        </IonHeader> */}
         <div className="inner-content !p-6">
            <ModalHeader disabled={loading} title="Weekly Savings - Print All" sub="System" dismiss={dismiss} />

          <div></div>
          <div className="text-end mt-4 space-x-2">
            <div className="text-center">
              <IonButton disabled={loading} onClick={handlePrint} fill="clear" className="w-full bg-zinc-50 rounded-lg ">
                <div className=' flex items-center justify-center gap-2 bg-zinc-50 !border-zinc-300 !border-1 p-3 w-full rounded-md'>
                  <div className=' p-2 bg-green-100 rounded-md flex items-center text-green-800'>
                    <PrinterIcon size={20} stroke='.8' className=' '/>
                  </div>
                  <div className=' flex flex-col !text-sm !text-black !font-medium capitalize text-start'>
                    {loading ? 'Printing Weekly Savings List...' : 'Weekly Savings'}
                    <p className=' text-xs text-zinc-500 capitalize'>Portable Document Format</p>

                  </div>
                </div>
                {/* {loading ? 'Printing Client Profile...' : 'Client Profile'} */}
              </IonButton>
            </div>
          </div>
        </div>
      </IonModal>
    </>
  );
};

export default PrintAllWeeklySavingsTable;
