import React, { useRef, useState } from 'react';
import { IonButton, IonModal, IonHeader, IonToolbar, useIonToast } from '@ionic/react';
import { useForm } from 'react-hook-form';
import { zodResolver } from '@hookform/resolvers/zod';
import ModalHeader from '../../../../ui/page/ModalHeader';
import { NatureFormData, natureSchema } from '../../../../../validations/nature.schema';
import kfiAxios from '../../../../utils/axios';
import { TErrorData, TFormError } from '../../../../../types/types';
import checkError from '../../../../utils/check-error';
import formErrorHandler from '../../../../utils/form-error-handler';
import { useOnlineStore } from '../../../../../store/onlineStore';
import { db } from '../../../../../database/db';
import FinancialStatementForm from './tb-form';
import { fschema, FSFormData } from '../../../../../validations/financialstatement.schema';
import TBForm from './tb-form';
import { tbchema, TBFormData } from '../../../../../validations/trial-balance-schema';

type CreateProps = {
  getList: (page: number) => void;
  currentPage: number
};

const CreateTB = ({ getList, currentPage }: CreateProps) => {
  const [loading, setLoading] = useState(false);

  const modal = useRef<HTMLIonModalElement>(null);
  const online = useOnlineStore((state) => state.online);
  const [present] = useIonToast();
  
  
  const form = useForm<TBFormData>({
    resolver: zodResolver(tbchema),
    defaultValues: {
    
    },
  });

  function dismiss() {
    form.reset();
    modal.current?.dismiss();
  }

  async function onSubmit(data: TBFormData) {
      setLoading(true);
     if(online){
       try {
        const result = await kfiAxios.post('/trial-balance', data);
        const { success } = result.data;
        if (success) {
          getList(1);
           present({
          message: 'Record successfully created. ',
          duration: 1000,
        });
          dismiss();
          return;
        }
      } catch (error: any) {
        const errs: TErrorData | string = error?.response?.data?.error || error.message;
        const errors: TFormError[] | string = checkError(errs);
        const fields: string[] = Object.keys(form.formState.defaultValues as Object);
        formErrorHandler(errors, form.setError, fields);
      } finally {
        setLoading(false);
      }
     } else {
      await db.trialBalance.add(
                    {
                    ...data, 
                    _synced: false,
                    entries: [],
                    action: "create",
                    isOldData: false
                  }
                  );
                  getList(currentPage);
                  dismiss()
                  present({
                        message: 'Data successfully created!.',
                        duration: 1000,
                      });
                  return;
          }
    
  }

  return (
    <>
      <div className="text-end">
        <IonButton fill="clear" id="create-tb-modal" className="max-h-10 min-h-6 bg-[#FA6C2F] text-white capitalize font-semibold rounded-md" strong>
          + Add
        </IonButton>
      </div>
      <IonModal
        ref={modal}
        trigger="create-tb-modal"
        backdropDismiss={false}
        className=" [--border-radius:0.35rem] auto-height [--width:95%] [--max-width:32rem]"
      >
        {/* <IonHeader>
          <IonToolbar className=" text-white [--min-height:1rem] h-20">
            <ModalHeader disabled={loading} title="Nature - Add Record" sub="System" dismiss={dismiss} />
          </IonToolbar>
        </IonHeader> */}
        <div className="p-6 flex flex-col gap-6">
           <ModalHeader disabled={loading} title="Trial Balance - Add Record" sub="Manage trial balance data." dismiss={dismiss} />
          <div>
            <form onSubmit={form.handleSubmit(onSubmit)}>
              <TBForm form={form} loading={loading} />
              <div className="text-end border-t mt-2 pt-1 space-x-2">
                <IonButton disabled={loading} color="tertiary" type="submit" className="!text-sm capitalize" strong={true}>
                  {loading ? 'Saving...' : 'Save'}
                </IonButton>
                <IonButton disabled={loading} onClick={dismiss} color="danger" type="button" className="!text-sm capitalize" strong={true}>
                  Cancel
                </IonButton>
              </div>
            </form>
          </div>
        </div>
      </IonModal>
    </>
  );
};

export default CreateTB;
