import { IonButton, IonContent, IonPage, useIonToast, useIonViewWillEnter } from '@ionic/react';
import React, { useState } from 'react';
import PageTitle from '../../../ui/page/PageTitle';
import { Table, TableBody, TableCell, TableHead, TableHeader, TableHeadRow, TableRow } from '../../../ui/table/Table';
import { canDoAction, haveActions } from '../../../utils/permissions';
import { AccessToken, EmergencyLoan as EmergencyLoanType, TTableFilter } from '../../../../types/types';
import { jwtDecode } from 'jwt-decode';
import TableLoadingRow from '../../../ui/forms/TableLoadingRow';
import TableNoRows from '../../../ui/forms/TableNoRows';
import { formatDateTable } from '../../../utils/date-utils';
import { formatMoney } from '../../../utils/number';
import TablePagination from '../../../ui/forms/TablePagination';
import EmergencyLoanFilter from './components/EmergencyLoanFilter';
import CreateEmergencyLoan from './modals/CreateEmergencyLoan';
import { TABLE_LIMIT } from '../../../utils/constants';
import kfiAxios from '../../../utils/axios';
import EmergencyLoanActions from './components/EmergencyLoanActions';
import PrintAllEmergencyLoan from './modals/prints/PrintAllEmergencyLoan';
import ExportAllEmergencyLoan from './modals/prints/ExportAllEmergencyLoan';
import { useOnlineStore } from '../../../../store/onlineStore';
import { db } from '../../../../database/db';
import { formatELList, formatEVList } from '../../../ui/utils/fomatData';
import { filterAndSortLoanRelease } from '../../../ui/utils/sort';
import { Upload } from 'lucide-react';

export type TData = {
  emergencyLoans: EmergencyLoanType[];
  totalPages: number;
  nextPage: boolean;
  prevPage: boolean;
  loading: boolean;
};

const EmergencyLoan = () => {
  const token: AccessToken = jwtDecode(localStorage.getItem('auth') as string);
  const permissions = JSON.parse(localStorage.getItem('permissions') || '[]')


  const [present] = useIonToast();

  const [currentPage, setCurrentPage] = useState<number>(1);
  const [searchKey, setSearchKey] = useState<string>('');
  const [sortKey, setSortKey] = useState<string>('');
  const [from, setFrom] = useState<string>('');
  const [to, setTo] = useState<string>('');
  const online = useOnlineStore((state) => state.online);
  const [uploading, setUploading] = useState<boolean>(false)

  const [data, setData] = useState<TData>({
    emergencyLoans: [],
    loading: false,
    totalPages: 0,
    nextPage: false,
    prevPage: false,
  });

  const getEmergencyLoans = async (page: number, keyword: string = '', sort: string = '', to: string = '', from: string = '') => {
    if(online){
      setData(prev => ({ ...prev, loading: true }));
      try {
        const filter: TTableFilter & { to?: string; from?: string } = { limit: TABLE_LIMIT, page };
        if (keyword) filter.search = keyword;
        if (sort) filter.sort = sort;
        if (to) filter.to = to;
        if (from) filter.from = from;

        const result = await kfiAxios.get('/emergency-loan', { params: filter });
        const { success, emergencyLoans, hasPrevPage, hasNextPage, totalPages } = result.data;
        if (success) {
          setData(prev => ({
            ...prev,
            emergencyLoans,
            totalPages: totalPages,
            nextPage: hasNextPage,
            prevPage: hasPrevPage,
          }));
          setCurrentPage(page);
          setSearchKey(keyword);
          setSortKey(sort);
          setFrom(from);
          setTo(to);
          return;
        }
      } catch (error) {
        present({
          message: 'Failed to get journal voucher records. Please try again',
          duration: 1000,
        });
      } finally {
        setData(prev => ({ ...prev, loading: false }));
      }
    } else {
      setData(prev => ({ ...prev, loading: true }));
       try {
         const limit = TABLE_LIMIT;
         let data = await db.emergencyLoans.toArray();
         const filteredData = data.filter(e => e.action !== 'delete');
        let allData = filterAndSortLoanRelease(filteredData, keyword, sort, from, to);
         console.log(allData)

         const totalItems = allData.length;
         const totalPages = Math.ceil(totalItems / limit);
         const start = (page - 1) * limit;
         const end = start + limit;
         const finalData = allData.slice(start, end);
         const hasPrevPage = page > 1;
         const hasNextPage = page < totalPages;
          setData(prev => ({
            ...prev,
            emergencyLoans: finalData,
            totalPages,
            prevPage: hasPrevPage,
            nextPage: hasNextPage,
          }));
         setCurrentPage(page);
         setSearchKey(keyword);
         setSortKey(sort);
         setFrom(from);
         setTo(to);
       } catch (error) {
         console.log(error)
         present({
           message: 'Failed to load records.',
           duration: 1000,
         });
       } finally {
         setData(prev => ({ ...prev, loading: false }));
       }
    }
  };

  const uploadChanges = async () => {
          setUploading(true)
          try {
            const list = await db.emergencyLoans.toArray();
            const offlineChanges = list.filter(e => e._synced === false);
          
    
            const result = await kfiAxios.put("sync/upload/emergency-loans", { emergencyLoans: offlineChanges });
            const { success } = result.data;
            if (success) {
              setUploading(false)
               present({
                  message: 'Offline changes saved!',
                  duration: 1000,
                });
              getEmergencyLoans(currentPage);
              setUploading(false)
    
            }
          } catch (error: any) {
              setUploading(false)
              console.log(error)
    
              present({
                message: `${error.response.data.error.message}`,
                duration: 1000,
              });
          }
      };

  const handlePagination = (page: number) => getEmergencyLoans(page, searchKey, sortKey);

  useIonViewWillEnter(() => {
    getEmergencyLoans(currentPage);
  });

  return (
    <IonPage className=" w-full flex items-center justify-center h-full bg-zinc-100">
      <IonContent className="[--background:#F4F4F5] max-w-[1920px] h-full" fullscreen>
        <div className="h-full flex flex-col items-stretch justify-start py-6 gap-4">
          <PageTitle pages={['Transaction', 'Emergency Loan']} />
          <div className="px-3 pb-3 flex-1 flex flex-col">
           
            <div className=" p-4 pb-5 bg-white rounded-xl flex-1 shadow-lg">
               <div className=" flex flex-col gap-4 flex-wrap">
               
                <div className="flex items-start flex-wrap">
                  <div>{canDoAction(token.role, permissions, 'emergency loan', 'create') && <CreateEmergencyLoan getEmergencyLoans={getEmergencyLoans} />}</div>
                  <div>{canDoAction(token.role, permissions, 'emergency loan', 'print') && <PrintAllEmergencyLoan />}</div>
                  <div>{canDoAction(token.role, permissions, 'emergency loan', 'export') && <ExportAllEmergencyLoan />}</div>
                 
                </div>

                 <div className="w-full flex-1 flex">
                  <EmergencyLoanFilter getEmergencyLoans={getEmergencyLoans} />
                </div>
              </div>
              <div className="relative overflow-auto rounded-xl mt-4">
                <Table>
                  <TableHeader>
                    <TableHeadRow>
                      <TableHead>CV Number</TableHead>
                      <TableHead>Date</TableHead>
                      <TableHead>Bank</TableHead>
                      <TableHead>CHK. No.</TableHead>
                      <TableHead>Amount</TableHead>
                      <TableHead>Encoded By</TableHead>
                      {haveActions(token.role, 'emergency loan', permissions, ['update', 'delete', 'visible', 'print', 'export']) && <TableHead>Actions</TableHead>}
                    </TableHeadRow>
                  </TableHeader>
                  <TableBody>
                    {data.loading && <TableLoadingRow colspan={8} />}
                    {!data.loading && data.emergencyLoans.length < 1 && <TableNoRows label="No Emergency Loan Record Found" colspan={8} />}
                    {!data.loading &&
                      data.emergencyLoans.length > 0 &&
                      data.emergencyLoans.map((emergencyLoan: EmergencyLoanType, i: number) => (
                        <TableRow key={emergencyLoan._id}>
                          <TableCell>{emergencyLoan.code}</TableCell>
                          <TableCell>{formatDateTable(emergencyLoan.date)}</TableCell>
                          <TableCell>{emergencyLoan.bank.description}</TableCell>
                          <TableCell>{emergencyLoan.checkNo}</TableCell>
                          <TableCell>{formatMoney(emergencyLoan.amount)}</TableCell>
                          <TableCell>{emergencyLoan.encodedBy?.username}</TableCell>
                          {haveActions(token.role, 'emergency loan', permissions, ['update', 'delete', 'visible', 'print', 'export']) && (
                            <TableCell>
                              <EmergencyLoanActions
                                emergencyLoan={emergencyLoan}
                                getEmergencyLoans={getEmergencyLoans}
                                setData={setData}
                                searchKey={searchKey}
                                sortKey={sortKey}
                                to={to}
                                from={from}
                                currentPage={currentPage}
                                setCurrentPage={setCurrentPage}
                                rowLength={data.emergencyLoans.length}
                              />
                            </TableCell>
                          )}
                        </TableRow>
                      ))}
                  </TableBody>
                </Table>
              </div>
            </div>
          </div>
          <TablePagination currentPage={currentPage} totalPages={data.totalPages} onPageChange={handlePagination} disabled={data.loading} />
        </div>
      </IonContent>
    </IonPage>
  );
};

export default EmergencyLoan;
