import { IonButton, IonHeader, IonIcon, IonModal, IonToolbar, useIonToast } from '@ionic/react';
import React, { useRef, useState } from 'react';
import kfiAxios from '../../../../../utils/axios';
import ModalHeader from '../../../../../ui/page/ModalHeader';
import { useForm } from 'react-hook-form';
import { z } from 'zod';
import { zodResolver } from '@hookform/resolvers/zod';
import { ExpenseVoucher } from '../../../../../../types/types';
import { fileTrayFullSharp } from 'ionicons/icons';
import PrintExportOptionForm from '../../components/PrintExportOptionForm';
import { FileExportIcon } from 'hugeicons-react';
import { File } from 'lucide-react';

export const expenseVoucherOptionSchema = z.object({
  option: z.string().optional().or(z.literal('')),
});

export type ExpenseVoucherOptionFormData = z.infer<typeof expenseVoucherOptionSchema>;

const ExportExpenseVoucher = ({ expenseVoucher }: { expenseVoucher: ExpenseVoucher }) => {
  const [present] = useIonToast();
  const [loading, setLoading] = useState(false);

  const modal = useRef<HTMLIonModalElement>(null);

  const form = useForm<ExpenseVoucherOptionFormData>({
    resolver: zodResolver(expenseVoucherOptionSchema),
    defaultValues: {
      option: 'summary',
    },
  });

  function dismiss() {
    form.reset();
    modal.current?.dismiss();
  }


  async function handlePrint() {
          setLoading(true);
          try {
                  const result = await kfiAxios.get(`/expense-voucher/export/file/${expenseVoucher._id}`, { responseType: 'blob' });

            const url = window.URL.createObjectURL(new Blob([result.data]));
            const a = document.createElement('a');
            a.href = url;
            a.download = 'clients.xlsx';
            a.click();
            window.URL.revokeObjectURL(url);
          } catch (error: any) {
            present({
              message: 'Failed to export records. Please try again',
              duration: 1000,
            });
          } finally {
            setLoading(false);
          }
        }

  return (
    <>
      {/* <div
        id={`export_expense_voucher_${expenseVoucher._id}`}
        className="w-full flex items-center justify-start gap-2 text-sm font-semibold cursor-pointer active:bg-slate-200 hover:bg-slate-50 text-slate-600 px-2 py-1"
      >
        <IonIcon icon={fileTrayFullSharp} className="text-[1rem]" /> Export
      </div> */}
      <IonButton
        type="button"
        id={`export_expense_voucher_${expenseVoucher._id}`}
        fill="clear"
       className=" capitalize text-sm !text-zinc-700 w-fit"
      >
        <File size={20} className=' mr-1'/>
        <span>Export</span>
      </IonButton>
      <IonModal
        ref={modal}
        trigger={`export_expense_voucher_${expenseVoucher._id}`}
        backdropDismiss={false}
        className=" [--border-radius:0.35rem] auto-height md:[--max-width:30rem] md:[--width:100%] lg:[--max-width:30rem] lg:[--width:40%] [--width:95%]"
      >
        {/* <IonHeader>
          <IonToolbar className=" text-white [--min-height:1rem] h-12">
            <ModalHeader disabled={loading} title="Expense Voucher - Export" sub="Transaction" dismiss={dismiss} />
          </IonToolbar>
        </IonHeader> */}
        <div className="inner-content !p-6">
            <ModalHeader disabled={loading} title="Expense Voucher - Export" sub="Manage expense voucher documents." dismiss={dismiss} />

          <form onSubmit={form.handleSubmit(handlePrint)}>
            {/* <PrintExportOptionForm form={form} loading={loading} /> */}
            <div className="mt-3">
              <IonButton disabled={loading} type="submit" fill="clear" className="w-full bg-[#FA6C2F] text-white rounded-md font-semibold capitalize">
                <FileExportIcon size={20} stroke='.8' className=' mr-1'/>
                {loading ? 'Exporting Expense Voucher...' : 'Export Expense Voucher'}
              </IonButton>
            </div>
          </form>
        </div>
      </IonModal>
    </>
  );
};

export default ExportExpenseVoucher;
