import React, { useEffect, useState } from 'react';
import { Table, TableBody, TableCell, TableHead, TableHeader, TableHeadRow, TableRow } from '../../../../ui/table/Table';
import { Acknowledgement, AcknowledgementEntry, Entry, ExpenseVoucher, ExpenseVoucherEntry, TTableFilter } from '../../../../../types/types';
import { TABLE_LIMIT } from '../../../../utils/constants';
import kfiAxios from '../../../../utils/axios';
import { useIonToast } from '@ionic/react';
import TablePagination from '../../../../ui/forms/TablePagination';
import { formatNumber, removeAmountComma } from '../../../../ui/utils/formatNumber';
import TableLoadingRow from '../../../../ui/forms/TableLoadingRow';
import TableNoRows from '../../../../ui/forms/TableNoRows';
import { formatDateTable } from '../../../../utils/date-utils';
import { useOnlineStore } from '../../../../../store/onlineStore';

export type TData = {
  entries: AcknowledgementEntry[];
  totalPages: number;
  nextPage: boolean;
  prevPage: boolean;
  loading: boolean;
};

type ViewEntriesProps = {
  isOpen: boolean;
  acknowledgement: Acknowledgement;
};

const ViewAcknowledgementEntries = ({ isOpen, acknowledgement }: ViewEntriesProps) => {
  const [present] = useIonToast();
  const [currentPage, setCurrentPage] = useState<number>(1);
  const online = useOnlineStore((state) => state.online);
  

  const [data, setData] = useState<TData>({
    entries: [],
    loading: false,
    totalPages: 0,
    nextPage: false,
    prevPage: false,
  });

  const getEntries = async (page: number) => {
    if(online){
      setData(prev => ({ ...prev, loading: true }));
      try {
        const filter: TTableFilter = { limit: TABLE_LIMIT, page };

        const result = await kfiAxios.get(`/acknowledgement/entries/${acknowledgement._id}`, { params: filter });
        const { success, entries, hasPrevPage, hasNextPage, totalPages } = result.data;
        if (success) {
          setData(prev => ({
            ...prev,
            entries: entries,
            totalPages: totalPages,
            nextPage: hasNextPage,
            prevPage: hasPrevPage,
          }));
          setCurrentPage(page);
          return;
        }
      } catch (error) {
        present({
          message: 'Failed to get entry records. Please try again',
          duration: 1000,
        });
      } finally {
        setData(prev => ({ ...prev, loading: false }));
      }
    } else {
      setData(prev => ({ ...prev, loading: true }));
       try {
         const allData = acknowledgement.entries
           .filter((e) => !e.deletedAt)
           .map((e) => ({
             ...e,
             debit: Number(removeAmountComma(e.debit || 0)),
             credit: Number(removeAmountComma(e.credit || 0)),
           }))
         setData(prev => ({
           ...prev,
           entries: allData,
           totalPages: 1,
           prevPage: false,
           nextPage: false,
         }));
         setCurrentPage(page);
       } catch (error) {
         console.log(error)
         present({
           message: 'Failed to load records.',
           duration: 1000,
         });
       } finally {
         setData(prev => ({ ...prev, loading: false }));
       }
    }
  };

  const handlePagination = (page: number) => getEntries(page);

  useEffect(() => {
    if (isOpen) {
      getEntries(1);
    }
  }, [isOpen]);

  return (
    <div className="pb-2 h-full flex flex-col">
      <div className="relative overflow-auto flex-1">
        <Table>
          <TableHeader>
            <TableHeadRow className="border-4 bg-slate-100 [&>th]:border-4 [&>th]:!px-2 [&>th]:!py-1.5 [&>th]:!font-normal  [&>th]:!text-xs">
              <TableHead>CV#</TableHead>
              <TableHead>Due Date</TableHead>
              <TableHead>Week</TableHead>
              <TableHead>Name</TableHead>
              <TableHead>Acct. Code</TableHead>
              <TableHead>Description</TableHead>
              <TableHead className="text-center">Debit</TableHead>
              <TableHead className="text-center">Credit</TableHead>
            </TableHeadRow>
          </TableHeader>
          <TableBody>
            {data.loading && <TableLoadingRow colspan={11} />}
            {!data.loading && data.entries.length < 1 && <TableNoRows label="No Entry Record Found" colspan={11} />}
            {!data.loading &&
              data.entries.map((entry: AcknowledgementEntry, index: number) => (
                <TableRow key={entry._id} className="border-b-0 [&>td]:border-4 [&>td]:!py-1 [&>td]:!text-[.8rem] [&>td]:!px-2">
                  <TableCell>{entry?.loanReleaseEntryId?.transaction?.code ? `CV#${entry?.loanReleaseEntryId?.transaction?.code}` : ''}</TableCell>
                  <TableCell>{entry?.loanReleaseEntryId?.transaction?.dueDate ? formatDateTable(entry?.loanReleaseEntryId?.transaction?.dueDate) : ''}</TableCell>
                  <TableCell>{entry?.loanReleaseEntryId?.transaction?.noOfWeeks}</TableCell>
                  <TableCell>{entry?.loanReleaseEntryId?.client?.name}</TableCell>
                  <TableCell>{entry?.acctCode?.code}</TableCell>
                  <TableCell>{entry?.acctCode?.description}</TableCell>
                  <TableCell className="text-end">{formatNumber(entry?.debit as number)}</TableCell>
                  <TableCell className="text-end">{formatNumber(entry?.credit as number)}</TableCell>
                </TableRow>
              ))}
          </TableBody>
        </Table>
      </div>
      <div className="pt-2">
        <TablePagination currentPage={currentPage} totalPages={data.totalPages} onPageChange={handlePagination} disabled={data.loading} />
      </div>

       <div className="px-3">
           <div className="grid grid-cols-3">
             <div className="flex items-center justify-start gap-2 text-sm border-4 px-2 py-1 [&>div]:!font-semibold">
               <div>Diff: </div>
               <div>{`${formatNumber((data.entries).reduce((acc, current) => acc + Number(removeAmountComma(current.debit ?? '')), 0) - data.entries.reduce((acc, current) => acc + Number(removeAmountComma(current.credit ?? '')), 0))}`}</div>
             </div>
             <div className="flex items-center justify-start gap-2 text-sm border-4 px-2 py-1 [&>div]:!font-semibold col-span-2">
               <div>Total: </div>
               <div>{`${acknowledgement.amount.toLocaleString()}`}</div>
             </div>
           </div>
      </div>
    </div>
  );
};

export default ViewAcknowledgementEntries;
